script:
card({ name: "Pixel board", icon: 'palette' });
const words = {
  hint: "Pick a colour, then tap squares. Tap again to clear.",
  clear: "Clear the board",
  painted: "{p0} squares painted",
};

const N = 12;
const palette = ['#e5484d', '#f97316', '#f5c400', '#1db98a', '#2e9bf0', '#8b5cf6', '#ffffff', '#1f2937'];

function init() {
  return { px: {}, pick: {} };
}

on.paint = (s, args, ctx) => {
  const cell = Math.min(N - 1, Math.floor(args.y * N)) * N + Math.min(N - 1, Math.floor(args.x * N));
  const color = s.pick[ctx.author] ?? 0;
  if (s.px[cell] === color) delete s.px[cell];
  else s.px[cell] = color;
};

on.color = (s, args, ctx) => {
  s.pick[ctx.author] = Math.min(palette.length - 1, Math.max(0, Math.floor(args.x * palette.length)));
};

on.clear = (s) => {
  s.px = {};
};

function view(s, me) {
  const shapes = [];
  for (const [cell, color] of Object.entries(s.px)) {
    const i = Number(cell);
    shapes.push(rect((i % N) / N, Math.floor(i / N) / N, 1 / N, 1 / N, { fill: palette[color] }));
  }
  for (let k = 1; k < N; k++) {
    shapes.push(line(k / N, 0, k / N, 1, { stroke: 'muted', width: 0.5 }));
    shapes.push(line(0, k / N, 1, k / N, { stroke: 'muted', width: 0.5 }));
  }
  const mine = s.pick[me.id] ?? 0;
  const swatches = palette.map((c, i) => circle((i + 0.5) / palette.length, 0.5, i === mine ? 0.36 : 0.28, { fill: c, stroke: i === mine ? 'fg' : 'muted', width: i === mine ? 3 : 1 }));
  const painted = Object.keys(s.px).length;
  return column([
    text(words.hint, { size: 'small', tone: 'muted', align: 'center' }),
    canvas({ ratio: palette.length, onTap: 'color', shapes: swatches, fill: 'bg' }),
    canvas({ ratio: 1, onTap: 'paint', shapes, fill: 'bg' }),
    row([
      text(words.painted.replace('{p0}', painted), { size: 'small', tone: 'muted' }),
      painted > 0 && button(words.clear, 'clear', null, { tone: 'muted' }),
    ], { align: 'between' }),
  ]);
}
